import Anthropic from "@anthropic-ai/sdk";

type ToolFn = (input: any) => Promise<string>;

const MAX_STEPS = 8;        // потолок шагов
const MAX_USD = 0.5;        // бюджет на одну задачу
const PRICE_IN = 3 / 1e6;   // $ за входной токен (иллюстративно)
const PRICE_OUT = 15 / 1e6; // $ за выходной токен (иллюстративно)

export async function runAgent(
  client: Pick<Anthropic, "messages">,
  task: string,
  tools: Anthropic.Tool[],
  impl: Record<string, ToolFn>,
) {
  const messages: Anthropic.MessageParam[] = [{ role: "user", content: task }];
  let spent = 0;

  for (let step = 1; step <= MAX_STEPS; step++) {
    const res = await client.messages.create({
      model: "claude-sonnet-5",
      max_tokens: 2048,
      tools,
      messages, // ВСЯ история, каждый раз
    });
    spent += res.usage.input_tokens * PRICE_IN + res.usage.output_tokens * PRICE_OUT;
    console.log("step " + step + ": stop_reason=" + res.stop_reason +
      " in=" + res.usage.input_tokens + " $" + spent.toFixed(4));

    // ход модели целиком (text + tool_use) уходит в историю как есть
    messages.push({ role: "assistant", content: res.content });

    if (res.stop_reason === "end_turn") {
      const text = res.content.filter((b) => b.type === "text").map((b) => b.text).join("");
      return { status: "done", text, steps: step, spent };
    }
    if (res.stop_reason === "pause_turn") continue; // серверный инструмент на паузе: шлём как есть
    if (res.stop_reason !== "tool_use") {
      // max_tokens, refusal, model_context_window_exceeded, stop_sequence
      return { status: "stopped", reason: res.stop_reason, steps: step, spent };
    }

    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of res.content) {
      if (block.type !== "tool_use") continue;
      try {
        const fn = impl[block.name];
        if (!fn) throw new Error("Unknown tool " + block.name);
        results.push({ type: "tool_result", tool_use_id: block.id, content: await fn(block.input) });
      } catch (e) {
        // НЕ бросаем: модель должна увидеть ошибку, чтобы сменить тактику
        results.push({ type: "tool_result", tool_use_id: block.id, is_error: true,
          content: "Error: " + (e as Error).message + ". Try a different URL or query." });
      }
    }
    messages.push({ role: "user", content: results }); // все результаты одним сообщением

    if (spent > MAX_USD) return { status: "stopped", reason: "budget", steps: step, spent };
  }
  return { status: "stopped", reason: "step_cap", steps: MAX_STEPS, spent };
}

